def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    seen = set()

    # Find components of object colors, treating the apparent noise colors as gaps.
    noise = {2, 9}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or color in noise or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                        (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            y0, y1, x0, x1 = min(ys), max(ys), min(xs), max(xs)
            # Rectangular objects with a few corrupted cells are restored.
            area = (y1-y0+1) * (x1-x0+1)
            if area >= 4 and len(cells) >= area * 0.45:
                for y in range(y0, y1+1):
                    for x in range(x0, x1+1):
                        out[y][x] = color

    # Remaining noise-colored cells are background.
    for r in range(h):
        for c in range(w):
            if grid[r][c] in noise:
                out[r][c] = bg
    return out
